<?php
require_once __DIR__.'/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Laporan';$activePage='laporan.php';$period=$_GET['period']??'bulanan';$today=date('Y-m-d');if($period==='harian'){$from=$today;$to=$today;}elseif($period==='mingguan'){$from=date('Y-m-d',strtotime('monday this week'));$to=date('Y-m-d',strtotime('sunday this week'));}elseif($period==='tahunan'){$from=date('Y-01-01');$to=date('Y-12-31');}elseif($period==='custom'){$from=validDate((string)($_GET['from']??''))?$_GET['from']:date('Y-m-01');$to=validDate((string)($_GET['to']??''))?$_GET['to']:date('Y-m-t');}else{$from=date('Y-m-01');$to=date('Y-m-t');$period='bulanan';}$income=transactionSum($pdo,$uid,'income',$from,$to);$expense=transactionSum($pdo,$uid,'expense',$from,$to);$saving=(float)$pdo->query("SELECT COALESCE(SUM(current_amount),0) FROM savings WHERE user_id={$uid}")->fetchColumn();$debt=(float)$pdo->query("SELECT COALESCE(SUM(GREATEST(total_amount-paid_amount,0)),0) FROM debts WHERE user_id={$uid}")->fetchColumn();$receivable=(float)$pdo->query("SELECT COALESCE(SUM(GREATEST(total_amount-paid_amount,0)),0) FROM receivables WHERE user_id={$uid}")->fetchColumn();$balance=$income-$expense;$net=$balance+$saving+$receivable-$debt;$st=$pdo->prepare('SELECT category,type,SUM(amount) total FROM transactions WHERE user_id=? AND transaction_date BETWEEN ? AND ? GROUP BY category,type ORDER BY total DESC');$st->execute([$uid,$from,$to]);$categories=$st->fetchAll();$st=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? AND transaction_date BETWEEN ? AND ? ORDER BY transaction_date DESC,id DESC');$st->execute([$uid,$from,$to]);$rows=$st->fetchAll();$user=currentUser($pdo);require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">Ringkasan terukur</p><h1>Laporan Keuangan</h1><p>Gunakan filter untuk membaca kondisi finansialmu dengan lebih jernih.</p></div><button class="btn btn-primary no-print" onclick="window.print()"><i data-lucide="printer"></i> Cetak Laporan</button></div>
<form class="toolbar glass-card no-print" method="get"><div class="toolbar-form"><select class="select" name="period"><option value="harian" <?=$period==='harian'?'selected':''?>>Harian</option><option value="mingguan" <?=$period==='mingguan'?'selected':''?>>Mingguan</option><option value="bulanan" <?=$period==='bulanan'?'selected':''?>>Bulanan</option><option value="tahunan" <?=$period==='tahunan'?'selected':''?>>Tahunan</option><option value="custom" <?=$period==='custom'?'selected':''?>>Custom</option></select><input class="input" type="date" name="from" value="<?=e($from)?>"><input class="input" type="date" name="to" value="<?=e($to)?>"><button class="btn btn-soft" type="submit"><i data-lucide="filter"></i> Terapkan</button></div></form>
<div class="card" style="margin-bottom:18px"><p class="eyebrow">Periode laporan</p><h2 class="card-title"><?=e(date('d/m/Y',strtotime($from)))?> — <?=e(date('d/m/Y',strtotime($to)))?></h2></div>
<div class="stats-grid"><div class="stat-card card"><div class="stat-top"><span>Total Pemasukan</span><span class="stat-icon"><i data-lucide="trending-up"></i></span></div><div class="stat-value positive"><?=formatRupiah($income)?></div></div><div class="stat-card card"><div class="stat-top"><span>Total Pengeluaran</span><span class="stat-icon"><i data-lucide="trending-down"></i></span></div><div class="stat-value negative"><?=formatRupiah($expense)?></div></div><div class="stat-card card"><div class="stat-top"><span>Sisa</span><span class="stat-icon"><i data-lucide="sparkles"></i></span></div><div class="stat-value"><?=formatRupiah($balance)?></div></div><div class="stat-card card"><div class="stat-top"><span>Net Worth</span><span class="stat-icon"><i data-lucide="badge-dollar-sign"></i></span></div><div class="stat-value"><?=formatRupiah($net)?></div><div class="stat-meta">Tabungan <?=formatRupiah($saving)?> · Utang <?=formatRupiah($debt)?></div></div></div>
<div class="grid-two"><section class="card"><div class="card-header"><div><h2 class="card-title">Komposisi kategori</h2><p class="card-subtitle">Ringkasan kategori periode ini</p></div></div><div class="chart-wrap"><canvas id="reportChart"></canvas></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Ringkasan kategori</h2><p class="card-subtitle">Diurutkan dari nominal terbesar</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Kategori</th><th>Jenis</th><th>Total</th></tr></thead><tbody><?php foreach($categories as $item):?><tr><td><?=e($item['category'])?></td><td><span class="badge <?=$item['type']==='income'?'success':'danger'?>"><?=$item['type']==='income'?'Pemasukan':'Pengeluaran'?></span></td><td class="amount"><?=formatRupiah($item['total'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="card"><div class="card-header"><div><h2 class="card-title">Transaksi dalam laporan</h2><p class="card-subtitle"><?=number_format(count($rows),0,',','.')?> transaksi</p></div></div><?php if(!$rows):?><div class="empty-state">Belum ada transaksi di periode ini.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Deskripsi</th><th>Nominal</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e(date('d/m/Y',strtotime($row['transaction_date'])))?></td><td><?=$row['type']==='income'?'Pemasukan':'Pengeluaran'?></td><td><?=e($row['category'])?></td><td><?=e($row['description']?:'—')?></td><td class="amount <?=$row['type']==='income'?'positive':'negative'?>"><?=formatRupiah($row['amount'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php $labels=array_map(fn($x)=>$x['category'],$categories);$values=array_map('floatval',array_column($categories,'total'));$pageScripts='<script>new Chart(document.getElementById("reportChart"),{type:"doughnut",data:{labels:'.json_encode($labels,JSON_UNESCAPED_UNICODE).',datasets:[{data:'.json_encode($values).',backgroundColor:["#5b62da","#18a999","#ec8b75","#e9aa43","#8e73dc","#4b9ec7"],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{font:{family:"Inter",size:10},usePointStyle:true,boxWidth:8}}}}});</script>';require __DIR__.'/includes/footer.php';